'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Interface language: saved on the server once logged in; before that, the browser's language.
const storedLang=()=>{try{return localStorage.getItem('atelier-lang')}catch{return null}};
let lang=storedLang()||((navigator.language||'').toLowerCase().startsWith('fr')?'fr':'en');
const t=(fr,en)=>lang==='en'?en:fr;
function setLang(next){lang=next==='fr'?'fr':'en';try{localStorage.setItem('atelier-lang',lang)}catch{}document.documentElement.lang=lang;document.title=t('Atelier — votre équipe d’agents','Atelier — your team of agents')}
setLang(lang);
const langSwitch=()=>`<div class="lang-switch" role="group" aria-label="${t('Langue','Language')}">${[['fr','FR'],['en','EN']].map(([k,l])=>`<button type="button" class="${lang===k?'active':''}" data-action="set-lang" data-id="${k}" aria-pressed="${lang===k}">${l}</button>`).join('')}</div>`;
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',agents:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',folder:'M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7z',mission:'M9 3h6v4H9z M9 5H6a2 2 0 0 0-2 2v13a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1V7a2 2 0 0 0-2-2h-3 M8 12h8 M8 16h5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',chevron:'m9 5 7 7-7 7',back:'M19 12H5 M10 7l-5 5 5 5',close:'m6 6 12 12 M6 18 18 6',play:'m8 4 12 8-12 8V4z',pause:'M8 5v14 M16 5v14',stop:'M5 5h14v14H5z',check:'m5 12 4 4L19 6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',file:'M14 2H5v20h14V7l-5-5z M14 2v6h5 M8 12h8 M8 16h6',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v5h16v-5',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3z',edit:'m16 3 5 5-12 12-6 1 1-6L16 3z M13 6l5 5',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',logout:'M9 3H3v18h6 M10 12h12 M17 7l5 5-5 5',info:'M12 11v6 M12 7v.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',menu:'M4 6h16 M4 12h16 M4 18h16',up:'m6 14 6-6 6 6',team:'M12 3v5 M5 16v-4h14v4 M12 8v4 M2 16h6v5H2z M16 16h6v5h-6z M9 3h6v5H9z'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.spark}"/></svg>`;
const labels=()=>({queued:t('En attente','Queued'),running:t('En cours','Running'),waiting:t('À valider','To approve'),paused:t('En pause','Paused'),completed:t('Terminée','Finished'),failed:t('À reprendre','To resume'),cancelled:t('Arrêtée','Stopped'),pending:t('À venir','Upcoming'),done:t('Terminé','Done')});
let state=null,route='overview',currentId='',detail=null,detailTab='activity',teamOrder=[],session=null,refreshing=false;
const badge=s=>`<span class="badge ${esc(s)}">${esc(labels()[s]||s)}</span>`;
const avatar=a=>`<span class="avatar ${esc(a.color||'peach')}">${esc((a.name||'A').slice(0,1))}</span>`;
const providerNames={claude:'Claude Code',codex:'Codex · ChatGPT',antigravity:'Gemini · Antigravity'};
const provider=p=>providerNames[p]||t('Assistant inconnu','Unknown assistant');
const efforts=()=>[['medium',t('Moyen · plus rapide','Medium · faster')],['high',t('Élevé · recommandé','High · recommended')],['xhigh',t('Très élevé','Very high')],['max',t('Maximal · plus lent, plus de quota','Maximum · slower, uses more quota')]];
const effortLabel=e=>(efforts().find(x=>x[0]===(e||'high'))||[])[1]?.split(' · ')[0]||e;
const locale=()=>t('fr-FR','en-GB');
const date=s=>new Date(s).toLocaleDateString(locale(),{day:'numeric',month:'short'});
const time=s=>new Date(s).toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit'});
const size=n=>n<1024?n+t(' o',' B'):n<1048576?(n/1024).toFixed(1)+t(' Ko',' KB'):(n/1048576).toFixed(1)+t(' Mo',' MB');
const find=(kind,id)=>state[kind].find(x=>x.id===id);
const button=(label,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
async function api(path,method='GET',data){const r=await fetch('./api'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-Atelier-Request':'1'},body:data===undefined?undefined:JSON.stringify(data)});let body;try{body=await r.json()}catch{throw Error(t('Le serveur ne répond pas correctement.','The server is not responding properly.'))}if(!r.ok){if(r.status===401&&path!='/login'){session={authenticated:false,configured:true};renderLogin()}throw Error(body.error||t('Une erreur est survenue.','Something went wrong.'))}return body}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function empty(title,text,action='',actionText=''){return `<div class="empty">${icon('spark')}<h3>${title}</h3><p>${text}</p>${action?button(actionText,action,'small'):''}</div>`}
function heading(title,sub,action='',label='',eyebrow=t('VOTRE ESPACE DE TRAVAIL','YOUR WORKSPACE')){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="sub">${sub}</p></div>${action?button(icon('plus')+label,action,'primary'):''}</div>`}
function demoHint(){return state.demo?`<div class="hint demo">${icon('info')}<span>${t('Aperçu interactif · Les données sont enregistrées ici, mais les missions sont simulées. Aucun appel à vos abonnements.','Interactive preview · Data is saved here, but missions are simulated. No call to your subscriptions.')}</span></div>`:''}
function shell(){const titles={overview:t('Vue d’ensemble','Overview'),agents:'Agents',teams:t('Équipes','Teams'),projects:t('Projets','Projects'),settings:t('Connexions & réglages','Connections & settings'),mission:t('Suivi de mission','Mission'),project:t('Votre projet','Your project')};const navs=[['overview','grid',titles.overview],['projects','folder',titles.projects]];const activeCount=state.missions.filter(m=>['running','queued','waiting'].includes(m.status)).length;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a href="#overview" class="brand"><img src="./favicon.svg" alt="">atelier<span><small>${t('BÊTA','BETA')}</small></span></a><div class="workspace"><div class="workspace-icon">${icon('folder')}</div><div><strong>${t('Mon atelier','My atelier')}</strong><small>${t('Espace personnel','Personal space')}</small></div></div><p class="navlabel">${t('Espace de travail','Workspace')}</p><nav class="nav">${navs.map(([r,i,l])=>`<a href="#${r}" class="${route===r||(r==='projects'&&['project','mission'].includes(route))?'active':''}">${icon(i)}${l}${r==='overview'&&activeCount?`<span class="count">${activeCount}</span>`:''}</a>`).join('')}</nav><div class="nav-bottom"><p class="navlabel">${t('Réglages','Settings')}</p><nav class="nav"><a href="#agents" class="${route==='agents'?'active':''}">${icon('agents')}Agents</a><a href="#teams" class="${route==='teams'?'active':''}">${icon('team')}${titles.teams}</a><a href="#settings" class="${route==='settings'?'active':''}">${icon('settings')}${titles.settings}</a></nav><div class="user"><span class="avatar">M</span><div><strong>${t('Mon espace','My space')}</strong><small>${state.demo?t('Mode démonstration','Demo mode'):t('Installation personnelle','Personal install')}</small></div>${!state.demo?`<button title="${t('Se déconnecter','Log out')}" aria-label="${t('Se déconnecter','Log out')}" data-action="logout">${icon('logout')}</button>`:''}</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="iconbtn mobile-menu" data-action="menu" aria-label="${t('Ouvrir le menu','Open the menu')}">${icon('menu')}</button><span>${t('Mon atelier','My atelier')}</span><span>/</span><strong>${titles[route]||titles.overview}</strong></div><div class="top-actions">${langSwitch()}<a href="#settings" class="connection-pill"><span class="dot ${state.demo?'amber':''}"></span>${state.demo?t('Démonstration','Demo'):t('Espace personnel','Personal space')}</a><span class="avatar lavender">M</span></div></header><div class="content" id="content"></div></main></div>`;renderPage()}
function missionRow(m){const done=m.status==='completed';return `<a class="mission-row" href="#mission/${m.id}${done?'?results':''}"><div class="mission-icon">${icon(m.status==='completed'?'check':'mission')}</div><div><h3>${esc(m.name)}</h3><p>${esc(m.project_name)} · ${date(m.created_at)}${m.execution==='demo'?t(' · Démo',' · Demo'):''}${done?t(' · Livrables prêts',' · Deliverables ready'):''}${(n=>n?' · '+n+t(' article(s) à télécharger',' article(s) to download'):'')(m.steps.reduce((k,s)=>k+(s.to_download||[]).length,0))}</p></div>${badge(m.status)}${icon('chevron')}</a>`}
function overview(){const followUp=state.missions.filter(m=>['running','queued','waiting','paused','failed'].includes(m.status));return heading(t('Bienvenue dans votre atelier.','Welcome to your atelier.'),t('Vos missions en cours et vos projets.','Your ongoing missions and your projects.'),'new-mission',t('Nouvelle mission','New mission'),t('VUE D’ENSEMBLE','OVERVIEW'))+demoHint()+`<div class="columns"><section class="panel"><div class="panel-title"><h2>${followUp.length?t('À suivre','To follow'):t('Vos dernières missions','Your latest missions')}</h2></div>${followUp.length?followUp.map(missionRow).join(''):state.missions.length?state.missions.slice(0,4).map(missionRow).join(''):empty(t('Votre première mission vous attend','Your first mission awaits'),t('Une analyse, un document ou une idée à explorer : donnez un objectif à votre équipe.','An analysis, a document or an idea to explore: give your team a goal.'),'new-mission',t('Lancer ma première mission','Start my first mission'))}</section><section class="panel"><div class="panel-title"><h2>${t('Vos projets','Your projects')}</h2><a href="#projects" class="textbtn">${t('Tout voir','See all')} ${icon('arrow')}</a></div>${state.projects.slice(0,4).map(p=>`<a class="agent-row" href="#project/${p.id}"><span class="avatar blue">${icon('folder')}</span><div><strong>${esc(p.name)}</strong><small>${state.missions.filter(m=>m.project_id===p.id).length} mission(s)</small></div>${icon('chevron')}</a>`).join('')||empty(t('Aucun projet','No project'),t('Créez un projet pour y déposer vos documents.','Create a project to store your documents.'),'new-project',t('Créer un projet','Create a project'))}</section></div>`}
function agentsPage(){return heading(t('Des talents pour chaque mission.','The right talent for every mission.'),t('Définissez le rôle et les consignes de chacun.','Set each agent’s role and instructions.'),'new-agent',t('Créer un agent','Create an agent'))+`<div class="cards">${state.agents.map(a=>`<article class="card"><div class="card-top">${avatar(a)}<span class="provider"><span class="dot"></span>${provider(a.provider)}</span></div><h3>${esc(a.name)}</h3><p class="card-description">${esc(a.role)}</p><div class="chips"><span class="chip">${esc(state.roles?.[a.preset]?.label||t('Rôle personnalisé','Custom role'))}</span><span class="chip">${t('Réflexion : ','Reasoning: ')}${esc(effortLabel(a.effort))}</span><span class="chip">${a.model?esc(a.model):t('Modèle par défaut','Default model')}</span><span class="chip">${state.teams.filter(x=>x.agent_ids.includes(a.id)).length} ${t('équipe(s)','team(s)')}</span></div><div class="card-footer"><button class="textbtn" data-action="edit-agent" data-id="${a.id}">${icon('edit')}${t('Configurer','Configure')}</button><button class="iconbtn" data-action="delete-agent" data-id="${a.id}" aria-label="${t('Supprimer','Delete')} ${esc(a.name)}">${icon('trash')}</button></div></article>`).join('')}</div>`}
function modeLabel(mode){return {relay:t('En relais','Relay'),parallel:t('Parallèle + synthèse','Parallel + synthesis'),arbitration:t('Créateurs + relecteur','Creators + reviewer')}[mode]||mode}
const modeHelp=()=>({arbitration:t('Les créateurs travaillent chacun de leur côté sur le même sujet ; le relecteur compare, combine, corrige et livre la version finale.','Creators each work on the same subject on their own; the reviewer compares, merges, corrects and delivers the final version.'),parallel:t('Les premiers agents explorent séparément ; le dernier rassemble leurs contributions.','The first agents explore separately; the last one brings their contributions together.'),relay:t('Chaque agent reçoit le travail du précédent et le poursuit.','Each agent receives the previous agent’s work and carries it on.')});
function teamCheck(team){const agents=team.agent_ids.map(id=>find('agents',id)).filter(Boolean);const n=new Set(agents.map(a=>a.provider)).size;const diverse=n>1?['ok','✓ '+n+t(' assistants différents : leurs erreurs se compensent',' different assistants: their mistakes offset each other')]:['warn',t('⚠ Un seul assistant : les agents risquent de faire les mêmes erreurs','⚠ A single assistant: the agents may make the same mistakes')];const free=team.mode==='relay'?['warn',t('⚠ En relais, chacun lit le travail précédent et tend à le valider','⚠ In a relay, each agent reads the previous work and tends to agree with it')]:['ok',t('✓ Les premiers agents travaillent sans se voir','✓ The first agents work without seeing each other')];return `<div class="team-check">${[diverse,free].map(([k,l])=>`<small class="${k}">${l}</small>`).join('')}</div>`}
function teamsPage(){return heading(t('Le travail d’équipe, simplement.','Teamwork, made simple.'),t('Combinez les bons rôles et choisissez comment ils collaborent.','Combine the right roles and choose how they work together.'),'new-team',t('Créer une équipe','Create a team'))+`<div class="cards">${state.teams.map(x=>`<article class="card"><div class="card-top"><span class="avatar mint">${icon('team')}</span><span class="badge">${modeLabel(x.mode)}</span></div><h3>${esc(x.name)}</h3><p class="card-description">${esc(x.description||modeHelp()[x.mode]||'')}</p><div class="stack">${x.agent_ids.map(id=>avatar(find('agents',id)||{name:'?'})).join('')}<span>${x.agent_ids.length} agents</span></div>${teamCheck(x)}<div class="card-footer"><button class="textbtn" data-action="edit-team" data-id="${x.id}">${icon('edit')}${t('Configurer','Configure')}</button><div class="inline-actions"><button class="iconbtn" data-action="delete-team" data-id="${x.id}" aria-label="${t('Supprimer','Delete')} ${esc(x.name)}">${icon('trash')}</button>${button(t('Utiliser ','Use ')+icon('arrow'),'use-team','small',`data-id="${x.id}"`)}</div></div></article>`).join('')}</div>`}
function projectsPage(){return heading(t('Un espace pour chaque projet.','A space for every project.'),t('Rassemblez vos documents, vos missions et leurs résultats.','Keep your documents, missions and results together.'),'new-project',t('Créer un projet','Create a project'))+`<div class="cards">${state.projects.map(p=>`<article class="card"><div class="card-top"><span class="avatar blue">${icon('folder')}</span><div class="inline-actions"><button class="iconbtn" data-action="edit-project" data-id="${p.id}" aria-label="${t('Renommer','Rename')} ${esc(p.name)}">${icon('edit')}</button><button class="iconbtn" data-action="delete-project" data-id="${p.id}" aria-label="${t('Supprimer','Delete')} ${esc(p.name)}">${icon('trash')}</button></div></div><h3>${esc(p.name)}</h3><p class="card-description">${esc(p.description||t('Votre espace de travail et vos documents.','Your workspace and documents.'))}</p><div class="card-footer"><span class="sub">${state.missions.filter(m=>m.project_id===p.id).length} mission(s)</span><a href="#project/${p.id}" class="textbtn">${t('Ouvrir','Open')} ${icon('arrow')}</a></div></article>`).join('')}</div>${!state.projects.length?`<div class="panel">${empty(t('Un endroit pour vos idées','A place for your ideas'),t('Créez votre premier projet et ajoutez les documents sur lesquels vos agents travailleront.','Create your first project and add the documents your agents will work on.'),'new-project',t('Créer mon premier projet','Create my first project'))}</div>`:''}`}
function settingsPage(){return heading(t('Votre atelier, bien connecté.','Your atelier, well connected.'),t('Retrouvez les connexions de vos assistants et les réglages de votre espace.','Your assistants’ connections and your workspace settings.'))+demoHint()+`<section class="setting-card"><div class="title-line"><div><h2>${t('Langue','Language')}</h2><p class="sub">${t('Langue de l’interface et des livrables des prochaines missions. Les consignes envoyées aux agents restent en anglais.','Language of the interface and of the deliverables of future missions. Instructions sent to the agents stay in English.')}</p></div>${langSwitch()}</div></section><section class="setting-card"><div class="title-line"><div><h2>${t('Vos assistants','Your assistants')}</h2><p class="sub">${t('L’application réutilise les comptes connectés sur la machine.','The app reuses the accounts logged in on the machine.')}</p></div>${button(t('Vérifier les connexions','Check connections'),'check-connections','small')}</div><div id="connections">${connectionsHTML(state.connections)}</div></section><section class="setting-card"><h2>${t('Contexte global','Global context')}</h2><p class="sub mb">${t('Ces consignes sont transmises à tous les agents, au début de chaque nouvelle mission. Les missions déjà créées gardent le contexte en vigueur à leur création.','These instructions are sent to every agent at the start of each new mission. Existing missions keep the context that applied when they were created.')}</p><form id="context-form">${textarea('global_context',t('Attentes permanentes','Standing expectations'),state.global_context||'',t('Ex. Sois toujours rigoureux : cite tes sources, distingue faits et hypothèses, reste concis.','E.g. Always be rigorous: cite your sources, separate facts from hypotheses, stay concise.'),'maxlength="8000"')}<div class="mt"><button class="btn small primary" type="submit">${t('Enregistrer le contexte','Save the context')}</button></div></form></section><section class="setting-card"><h2>${t('Niveau esthétique attendu','Expected design level')}</h2><p class="sub mb">${t('Déposez jusqu’à trois exemples réussis par format (une présentation, un rapport…). Quand une mission demande ce format, l’agent final les reçoit avec un aperçu de leurs pages et vise au moins ce niveau. Pour PowerPoint et Word, votre exemple sert aussi de modèle de mise en forme quand l’agent ne construit pas le fichier lui-même.','Upload up to three good examples per format (a deck, a report…). When a mission asks for that format, the final agent receives them with page previews and aims at least that high. For PowerPoint and Word, your example also serves as the layout template when the agent does not build the file itself.')}</p>${formats().map(([id,l])=>`<div class="reference-row">${formatLogo(id,28)}<div class="reference-files"><strong>${l}</strong><div class="chips">${(state.references?.[id]||[]).map(x=>`<span class="chip">${esc(x.name)}<button type="button" class="chip-x" data-action="delete-reference" data-format="${id}" data-name="${esc(x.name)}" aria-label="${t('Retirer','Remove')} ${esc(x.name)}">${icon('close')}</button></span>`).join('')||`<small class="sub">${t('Aucun exemple','No example')}</small>`}</div></div><label class="btn small">${icon('upload')}${t('Ajouter','Add')}<input type="file" class="reference-upload" data-format="${id}" accept=".pptx,.pdf,.docx,.tex,.png,.jpg,.jpeg" hidden></label></div>`).join('')}</section><section class="setting-card"><h2>${t('Fonctionnement de cette version','How this version works')}</h2><p class="sub">${t('Un espace personnel, deux missions simultanées, jusqu’à six agents par équipe. Chaque mission conserve ses documents, ses consignes et ses résultats. Les précisions ajoutées pendant le travail seront lues à l’étape suivante.','One personal space, two missions at a time, up to six agents per team. Each mission keeps its documents, instructions and results. Notes added during the work are read at the next step.')}</p><div class="chips"><span class="chip">${t('Stockage sur votre machine','Stored on your machine')}</span><span class="chip">${t('Claude, ChatGPT et Google · comptes connectés','Claude, ChatGPT and Google · logged-in accounts')}</span><span class="chip">Version ${esc(state.version)}</span></div></section><section class="setting-card"><h2>${t('Permissions et exécution','Permissions and execution')}</h2><p class="sub">${t('Codex s’exécute sans son bac à sable (indisponible dans la plupart des conteneurs) : il peut lancer des commandes sur la machine. Claude lit et écrit des fichiers et consulte le web, sans terminal. Gemini · Antigravity est limité au dossier de mission, sans terminal, MCP ni web. En lecture seule, le dossier de mission est verrouillé. La validation du dashboard intervient entre les étapes ; elle n’approuve pas les commandes internes des assistants.','Codex runs without its sandbox (unavailable in most containers): it can run commands on the machine. Claude reads and writes files and browses the web, without a terminal. Gemini · Antigravity is limited to the mission folder, with no terminal, MCP or web. In read-only mode, the mission folder is locked. Dashboard approval happens between steps; it does not approve the assistants’ internal commands.')}</p></section>${!state.demo?`<section class="setting-card"><h2>${t('Accès au dashboard','Dashboard access')}</h2><p class="sub mb">${t('Votre mot de passe protège cet espace personnel.','Your password protects this personal space.')}</p>${button(t('Changer le mot de passe','Change the password'),'password','small')}</section>`:''}<p class="footer-note">${t('Atelier · Vos agents, votre espace de travail.','Atelier · Your agents, your workspace.')}</p>`}
function connectionsHTML(items){const names={demo:t('Aperçu simulé','Simulated preview'),unchecked:t('À vérifier','To check'),missing:t('À installer','To install'),connected:t('Connecté','Connected'),disconnected:t('Connexion à renouveler','Login to renew'),unavailable:t('Vérification indisponible','Check unavailable'),signed_in:t('Compte connecté','Account connected')};const account={claude:t('Compte Claude','Claude account'),codex:t('Compte ChatGPT','ChatGPT account'),antigravity:t('Compte Google','Google account')};return items.map(c=>{if(c.id==='antigravity')return antigravityRow(c);return `<div class="connection-row"><div><strong>${provider(c.id)}</strong><small>${account[c.id]} · ${c.installed?t('Assistant détecté','Assistant found'):t('Assistant non détecté sur cette machine','Assistant not found on this machine')}</small>${c.detail?`<small class="connection-detail">${esc(c.detail)}</small>`:''}</div><span class="badge ${c.status==='connected'?'completed':c.status==='demo'?'demo':'waiting'}">${names[c.status]||esc(c.status)}</span></div>`}).join('')}
function antigravityRow(c){const v=c.verified;const checked=['signed_in','disconnected','unavailable'].includes(c.status);const account=c.status==='signed_in'?t('✓ Compte Google connecté','✓ Google account connected'):c.status==='disconnected'?t('✗ Compte Google non connecté','✗ Google account not connected'):checked?t('? Compte non vérifiable','? Account cannot be checked'):t('… Compte à vérifier (bouton « Vérifier les connexions »)','… Account to check (“Check connections” button)');const mission=v?t('✓ Mission réelle réussie le ','✓ Real mission succeeded on ')+`${esc(new Date(v.at).toLocaleString(locale()))} (${esc(v.source)}${v.model?' · '+esc(v.model):''})`:t('… Aucune mission réelle vérifiée','… No real mission verified');const state_=c.status==='demo'?['demo',t('Aperçu simulé','Simulated preview')]:!c.installed?['waiting',t('À installer','To install')]:c.status==='disconnected'?['waiting',t('Connexion à renouveler','Login to renew')]:v&&c.status!=='unavailable'?['completed',t('Mission vérifiée','Mission verified')]:c.status==='signed_in'?['waiting',t('Compte connecté','Account connected')]:['waiting',t('À vérifier','To check')];return `<div class="connection-row"><div><strong>${provider(c.id)}</strong><small>${c.installed?t('✓ Programme installé','✓ Program installed')+(c.version?' · version '+esc(c.version):''):t('✗ Programme « agy » non détecté sur cette machine','✗ “agy” program not found on this machine')}</small><small>${account}</small><small>${mission}</small>${c.detail?`<small class="connection-detail">${esc(c.detail)}</small>`:''}${c.permission_warning?`<small class="connection-detail">⚠ ${esc(c.permission_warning)}</small>`:''}${c.models&&c.models.length?`<small class="connection-detail">${t('Modèles disponibles : ','Available models: ')}${c.models.map(esc).join(', ')}</small>`:''}${c.installed&&!state.demo?`<div class="mt">${button(t('Tester une mission réelle','Test a real mission'),'test-antigravity','small')}</div>`:''}</div><span class="badge ${state_[0]}">${state_[1]}</span></div>`}
function eventHTML(e){return `<article class="event ${esc(e.kind)}"><div class="event-head"><strong>${esc(e.agent||(e.kind==='user'?t('Vous','You'):'Atelier'))}</strong><span>${time(e.at)}</span></div>${e.kind==='result'?`<details><summary>${t('Contribution disponible','Contribution available')}</summary><div class="result-content">${esc(e.text)}</div></details>`:`<p>${esc(e.text)}</p>`}</article>`}
function fileHTML(f,kind,id,remove=false){return `<div class="file-row">${icon('file')}<div><strong>${esc(f.name)}</strong><small>${esc(f.path)} · ${size(f.size)}</small></div><a class="iconbtn" href="./api/${kind}/${id}/files?path=${encodeURIComponent(f.path)}" aria-label="${t('Télécharger','Download')} ${esc(f.name)}">${icon('download')}</a>${remove?`<button class="iconbtn" data-action="delete-file" data-path="${esc(f.path)}" aria-label="${t('Supprimer','Delete')} ${esc(f.name)}">${icon('trash')}</button>`:''}</div>`}
const links=s=>esc(s).replace(/https?:\/\/[^\s<>"')\]»]+/g,u=>{u=u.replace(/[.,;:]+$/,'');return `<a href="${u}" target="_blank" rel="noopener noreferrer">${u}</a>`}).replace(/\b(10\.\d{4,9}\/[^\s<>"')\]»]+)/g,(d,_,i,all)=>all.slice(Math.max(0,i-9),i).includes('doi.org/')||all.slice(Math.max(0,i-6),i).includes('href=')?d:`<a href="https://doi.org/${d.replace(/[.,;:]+$/,'')}" target="_blank" rel="noopener noreferrer">${d}</a>`);
function downloadsHTML(m){const items=m.steps.flatMap((s,i)=>(s.to_download||[]).map(d=>[d,s.agent.name,i]));if(!items.length)return '';return `<section class="downloads-callout"><h2>${icon('download')}${t('Remarques : ','Notes: ')}${items.length}${t(' article(s) à télécharger vous-même',' article(s) to download yourself')}</h2><p>${t('Ces articles semblent utiles à la mission, mais leur accès est refusé aux agents (abonnement, accès réservé). Téléchargez-les avec votre propre accès, ajoutez-les aux documents du projet, puis relancez une mission : les agents pourront alors les lire.','These articles look useful for the mission, but the agents cannot access them (subscription, restricted access). Download them with your own access, add them to the project documents, then run a new mission: the agents will be able to read them.')}</p><ul>${items.map(([d,n,i])=>`<li>${links(d)} <small>${t('signalé par','flagged by')} ${esc(n)}</small><button class="iconbtn dismiss" data-action="dismiss-download" data-step="${i}" data-text="${esc(d)}" aria-label="${t('Masquer cette remarque','Hide this note')}" title="${t('Masquer cette remarque','Hide this note')}">${icon('close')}</button></li>`).join('')}</ul><a class="btn small" href="#project/${m.project_id}">${icon('upload')}${t('Ajouter aux documents de « ','Add to the documents of “')}${esc(m.project_name)}${t(' »','”')}</a></section>`}
function deleteNotice(kind,o){if(kind==='projects'){const n=state.missions.filter(m=>m.project_id===o.id).length;return t('Le projet, ses documents'+(n?' et ses '+n+' mission(s), avec leurs livrables,':'')+' seront effacés.','The project, its documents'+(n?' and its '+n+' mission(s), with their deliverables,':'')+' will be erased.')}if(kind==='missions')return t('La mission, son journal et ses livrables seront effacés. Les documents du projet sont conservés.','The mission, its log and its deliverables will be erased. The project documents are kept.');if(kind==='agents'){const teams=state.teams.filter(x=>x.agent_ids.includes(o.id)).map(x=>x.name);return (teams.length?t('L’agent sera retiré des équipes : ','The agent will be removed from these teams: ')+esc(teams.join(', '))+'. ':'')+t('Les missions passées gardent leur historique.','Past missions keep their history.')}return t('Les agents de l’équipe sont conservés. Les missions passées gardent leur historique.','The team’s agents are kept. Past missions keep their history.')}
function missionDetail(){const m=detail;if(!m)return `<p class="sub">${t('Chargement de la mission…','Loading the mission…')}</p>`;let actions='';if(['queued','running'].includes(m.status)){actions+=button(icon('pause')+(m.pause_requested?t('Pause demandée','Pause requested'):t('Mettre en pause','Pause')),'pause-mission','small',m.pause_requested?'disabled':'')}if(['waiting','paused','failed'].includes(m.status)){actions+=button(icon('play')+(m.status==='waiting'?t('Valider et continuer','Approve and continue'):t('Reprendre','Resume')),'resume-mission','primary small')}if(['running','queued','waiting','paused'].includes(m.status))actions+=button(icon('stop')+t('Arrêter','Stop'),'stop-mission','small');if(m.status==='completed')actions+=button(icon('edit')+t('Demander une retouche','Ask for a revision'),'revise-mission','primary small');if(!['running','queued'].includes(m.status))actions+=button(icon('trash')+t('Supprimer','Delete'),'delete-mission','danger small',`data-id="${m.id}"`);return `<div class="detail-header"><div><a href="#project/${m.project_id}" class="back">${icon('back')}${esc(m.project_name)}</a><h1>${esc(m.name)}</h1><div class="detail-meta">${badge(m.status)}<span>${esc(m.project_name)} · ${date(m.created_at)}</span>${(m.formats||[]).map(f=>`<span title="${esc(formats().find(x=>x[0]===f)?.[1]||f)}">${formatLogo(f,22)}</span>`).join('')}${m.execution==='demo'?`<span class="badge demo">${t('Démo','Demo')}</span>`:''}</div></div><div class="detail-actions">${actions}</div></div>${m.status==='waiting'?`<div class="note-callout">${t('Une étape est terminée. Consultez les contributions puis cliquez sur « Valider et continuer » pour lancer la suite.','A step is finished. Review the contributions, then click “Approve and continue” to go on.')}</div>`:''}${m.status==='failed'?`<div class="note-callout">${t('Un agent n’a pas pu terminer. Consultez le journal ci-dessous, vérifiez les connexions si nécessaire, puis reprenez la mission.','An agent could not finish. Read the log below, check the connections if needed, then resume the mission.')}</div>`:''}${downloadsHTML(m)}<div class="detail-grid"><section class="panel"><div class="tabs">${[['activity',t('Activité','Activity')],['results',t('Livrables','Deliverables')],['brief',t('Consignes','Brief')]].map(([id,l])=>`<button class="tab ${detailTab===id?'active':''}" data-action="detail-tab" data-id="${id}">${l}${id==='results'&&m.files.length?' · '+m.files.length:''}</button>`).join('')}</div><div class="panel-body" id="detail-body">${detailTab==='activity'?`<div class="timeline">${m.events.map(eventHTML).join('')}</div>`:detailTab==='results'?`${m.files.length?`${m.files.map(f=>fileHTML(f,'missions',m.id)).join('')}<p class="field-help mt"><a href="./api/missions/${m.id}/archive">${t('Fichiers de travail des agents','Agents’ working files')} (${m.work_files}, ${t('archive ZIP','ZIP archive')})</a></p>`:empty(t('Les résultats arrivent ici','Results arrive here'),t('Les contributions deviennent disponibles au fur et à mesure.','Contributions become available as the work progresses.'))}${m.steps.filter(s=>s.status==='done').map(s=>`<details class="mt"><summary class="textbtn">${t('Lire la contribution de ','Read the contribution of ')}${esc(s.agent.name)}</summary><div class="result-content">${esc(s.result)}</div></details>`).join('')}`:`<p class="smallcaps">${t('OBJECTIF','GOAL')}</p><div class="prose">${esc(m.brief)}</div>${m.rules.length?`<div class="divider"></div><p class="smallcaps">${t('RÈGLES APPLIQUÉES','RULES APPLIED')}</p><div class="prose">${esc(m.rules.map(x=>x.text||x).join('\n\n'))}</div>`:''}<div class="chips"><span class="chip">${m.allow_write?t('Création de fichiers autorisée','File creation allowed'):t('Lecture seule','Read-only')}</span><span class="chip">${m.timeout_minutes} min / agent</span><span class="chip">${m.review?t('Validation entre étapes','Approval between steps'):t('Enchaînement automatique','Automatic sequence')}</span></div>`}</div>${detailTab==='activity'?`<form class="note-form" id="note-form"><input name="text" aria-label="${t('Ajouter une précision','Add a note')}" placeholder="${t('Une précision pour la prochaine étape…','A note for the next step…')}" required maxlength="6000"><button class="btn primary" type="submit" aria-label="${t('Envoyer la précision','Send the note')}">${icon('arrow')}</button></form>`:''}</section><aside><section class="panel"><div class="panel-title"><h2>${esc(m.team_name)}</h2></div><div class="progressbar">${m.steps.map(s=>`<span class="${s.status==='done'?'complete':''}"></span>`).join('')}</div>${m.steps.map(s=>`<div class="step">${avatar(s.agent)}<div><strong>${esc(s.agent.name)}${s.revision?t(' · retouche',' · revision'):''}</strong><small>${s.revision?esc(s.revision.slice(0,80)):provider(s.agent.provider)}</small></div>${badge(s.status)}</div>`).join('')}</section><section class="setting-card mt"><h2>${modeLabel(m.mode)}</h2><p class="sub">${modeHelp()[m.mode]||''}</p></section></aside></div>`}
async function projectDetail(){const p=find('projects',currentId);if(!p){$('#content').innerHTML=empty(t('Projet introuvable','Project not found'),t('Retournez à la liste des projets.','Go back to the list of projects.'));return}const files=await api('/projects/'+p.id+'/files');if(route!=='project'||currentId!==p.id)return;$('#content').innerHTML=`<div class="detail-header"><div><a href="#projects" class="back">${icon('back')}${t('Tous les projets','All projects')}</a><h1>${esc(p.name)}</h1></div><div class="detail-actions">${button(icon('edit')+t('Renommer','Rename'),'edit-project','',`data-id="${p.id}"`)}${button(icon('trash')+t('Supprimer le projet','Delete the project'),'delete-project','danger',`data-id="${p.id}"`)}${button(icon('plus')+t('Nouvelle mission','New mission'),'new-mission','primary')}</div></div><div class="columns"><section class="panel"><div class="panel-title"><h2>${t('Missions du projet','Project missions')}</h2></div>${state.missions.filter(m=>m.project_id===p.id).map(missionRow).join('')||empty(t('Votre projet est prêt','Your project is ready'),t('Ajoutez vos documents puis confiez une mission à votre équipe.','Add your documents, then give your team a mission.'),'new-mission',t('Créer une mission','Create a mission'))}</section><section class="panel"><div class="panel-title"><h2>${t('Documents sources','Source documents')}</h2></div><div class="panel-body"><label class="upload-box">${icon('upload')}${t('Ajouter des fichiers','Add files')}<input id="upload" type="file" multiple><p class="field-help">${t('20 Mo par fichier · Les missions utilisent une copie de vos documents.','20 MB per file · Missions use a copy of your documents.')}</p></label><div class="mt">${files.map(f=>fileHTML(f,'projects',p.id,true)).join('')}</div></div></section></div><section class="setting-card mt"><h2>${t('Contexte du projet','Project context')} <span class="field-help">${t('(facultatif)','(optional)')}</span></h2><p class="sub mb">${t('Transmis à tous les agents des prochaines missions de ce projet.','Sent to every agent of this project’s future missions.')}</p><form id="project-context-form">${textarea('project_context',t('Contexte','Context'),p.description||'',t('Ex. Public visé, ton attendu, contraintes, ce qui a déjà été fait…','E.g. Target audience, expected tone, constraints, what has already been done…'),'maxlength="3000"')}<div class="mt"><button class="btn small primary" type="submit">${t('Enregistrer le contexte','Save the context')}</button></div></form></section>`}
function renderPage(){if(!state||!$('#content'))return;const pages={overview,agents:agentsPage,teams:teamsPage,projects:projectsPage,settings:settingsPage,mission:missionDetail};if(route==='project'){projectDetail().catch(e=>toast(e.message));return}$('#content').innerHTML=(pages[route]||overview)()}
async function navigate(){const raw=location.hash.slice(1)||'overview';const [r,id]=raw.split('/');route=r;currentId=(id||'').split('?')[0];if(!['overview','agents','teams','projects','settings','mission','project'].includes(route))route='overview';detail=null;if($('.modal'))$('#modal-root').innerHTML='';if(raw.includes('?results'))detailTab='results';else detailTab='activity';shell();if(route==='mission'){try{const m=await api('/missions/'+currentId);if(route==='mission'&&m.id===currentId){detail=m;renderPage()}}catch(e){toast(e.message)}}}
function field(name,label,value='',placeholder='',type='text',extra=''){return `<div class="field"><label class="label" for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${extra}></div>`}
function textarea(name,label,value='',placeholder='',extra=''){return `<div class="field"><label class="label" for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" placeholder="${esc(placeholder)}" ${extra}>${esc(value)}</textarea></div>`}
function select(name,label,options,value){return `<div class="field"><label class="label" for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`}
let lastFocus=null;
function modal(title,subtitle,body,form,submit=t('Enregistrer','Save'),id=''){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="iconbtn" data-action="close-modal" aria-label="${t('Fermer','Close')}">${icon('close')}</button></div><form id="modal-form" data-form="${form}" data-id="${esc(id)}"><div class="modal-body"><div class="form-error hidden" id="form-error" role="alert"></div>${body}</div><div class="modal-footer">${button(t('Annuler','Cancel'),'close-modal')}<button class="btn primary" type="submit">${submit}${icon('arrow')}</button></div></form></section></div>`;setTimeout(()=>$('.modal input:not([type=checkbox]),.modal textarea,.modal select')?.focus(),50)}
function closeModal(){$('#modal-root').innerHTML='';lastFocus?.focus?.()}
function roleFields(preset,a={}){const r=state.roles?.[preset];return r?`<details class="field"><summary class="textbtn">${t('Voir la méthode transmise à l’agent','See the method sent to the agent')}</summary><div class="prose mt">${esc(r.method)}</div></details>${textarea('instructions',t('Consignes supplémentaires (facultatif)','Extra instructions (optional)'),a.instructions||'',t('Ex. Spécialité, ton, points d’attention…','E.g. Specialty, tone, points to watch…'),'maxlength="12000"')}`:field('role',t('Son rôle','Role'),a.role||'',t('Ex. Explorer les données et expliquer les tendances','E.g. Explore the data and explain the trends'),'text','maxlength="120"')+textarea('instructions',t('Ses consignes','Instructions'),a.instructions||'',t('Décrivez sa méthode, les résultats attendus et les points à vérifier.','Describe the method, the expected results and the points to check.'),'required maxlength="12000"')}
function agentModal(id){const a=id?find('agents',id):{name:'',role:'',provider:'claude',model:'',instructions:'',color:'peach',preset:'createur',effort:'high'};const preset=a.preset||'';modal(id?t('Configurer votre agent','Configure your agent'):t('Un nouvel agent','A new agent'),t('Choisissez un rôle : sa méthode de travail est déjà rédigée.','Pick a role: its working method is already written.'),select('preset',t('Rôle','Role'),[...Object.entries(state.roles||{}).map(([k,r])=>[k,r.label+' · '+r.role]),['',t('Personnalisé · vos propres consignes','Custom · your own instructions')]],preset)+`<div id="role-fields">${roleFields(preset,a)}</div><div class="form-grid">${select('provider','Assistant',Object.entries(providerNames),a.provider)}${select('effort',t('Niveau de réflexion','Reasoning level'),efforts(),a.effort||'high')}</div><p class="field-help">${t('Plus l’agent réfléchit, plus son travail est approfondi, mais plus il est long et consomme de quota.','The more the agent thinks, the deeper its work, but the longer it takes and the more quota it uses.')}</p>${select('color',t('Couleur','Colour'),[['peach',t('Argile','Clay')],['mint',t('Sauge','Sage')],['lavender',t('Lavande','Lavender')],['blue',t('Brume','Mist')]],a.color)}`+field('name',t('Nom (facultatif)','Name (optional)'),a.name,t('Par défaut, le nom du rôle','Defaults to the role name'),'text','maxlength="100"')+`<details><summary class="textbtn">${t('Réglage avancé','Advanced setting')}</summary><div class="mt">${field('model',t('Modèle (facultatif)','Model (optional)'),a.model,t('Laisser vide pour le modèle par défaut','Leave empty for the default model'),'text','maxlength="100"')}<p class="field-help">${t('Utilisez un identifiant de modèle disponible dans votre abonnement. Pour Gemini · Antigravity, reprenez un identifiant listé dans Réglages (commande « agy models »).','Use a model ID available in your subscription. For Gemini · Antigravity, use an ID listed in Settings (“agy models” command).')}</p></div></details>`,'agents',t('Enregistrer l’agent','Save the agent'),id)}
function teamChoices(){return teamOrder.map((id,i)=>{const a=find('agents',id);return `<div class="agent-choice">${avatar(a)}<div class="label-info"><strong>${esc(a.name)}</strong><small>${esc(a.role)}</small></div><span class="order">${i+1}</span><button type="button" class="iconbtn" data-action="team-up" data-id="${id}" aria-label="${t('Monter','Move up')} ${esc(a.name)}" ${i===0?'disabled':''}>${icon('up')}</button><button type="button" class="iconbtn" data-action="team-remove" data-id="${id}" aria-label="${t('Retirer','Remove')} ${esc(a.name)}">${icon('close')}</button></div>`}).join('')+`<div class="inline-actions mt"><select id="team-add-agent" aria-label="${t('Choisir un agent à ajouter','Choose an agent to add')}"><option value="">${t('Ajouter un agent…','Add an agent…')}</option>${state.agents.filter(a=>!teamOrder.includes(a.id)).map(a=>`<option value="${a.id}">${esc(a.name)} · ${provider(a.provider)}</option>`).join('')}</select></div>`}
function modeChoice(mode,current,title){return `<label class="choice"><input type="radio" name="mode" value="${mode}" ${mode===current?'checked':''}><div><strong>${title}</strong><small>${modeHelp()[mode]}</small></div></label>`}
function teamModal(id){const team=id?find('teams',id):{name:'',agent_ids:[],mode:'arbitration'};teamOrder=[...team.agent_ids];modal(id?t('Composer votre équipe','Build your team'):t('Les bons talents, ensemble.','The right talent, together.'),t('Choisissez vos agents ; le relecteur passe toujours en dernier.','Choose your agents; the reviewer always goes last.'),field('name',t('Nom de l’équipe','Team name'),team.name,t('Ex. Deux créateurs, un relecteur','E.g. Two creators, one reviewer'),'text','required maxlength="100"')+`<label class="label">${t('Les agents, dans l’ordre','The agents, in order')}</label><div id="team-choices">${teamChoices()}</div><p class="field-help">${t('Le dernier agent de la liste livre le résultat final. Maximum : 6 agents.','The last agent in the list delivers the final result. Maximum: 6 agents.')}</p><label class="label mt">${t('Comment travaillent-ils ?','How do they work?')}</label>${modeChoice('arbitration',team.mode,t('Créateurs + relecteur · recommandé','Creators + reviewer · recommended'))}<details class="mt" ${team.mode!=='arbitration'?'open':''}><summary class="textbtn">${t('Options avancées','Advanced options')}</summary>${modeChoice('relay',team.mode,t('En relais','Relay'))}${modeChoice('parallel',team.mode,t('En parallèle + synthèse','Parallel + synthesis'))}</details>`,'teams',t('Enregistrer l’équipe','Save the team'),id)}
function projectModal(id){const p=id?find('projects',id):{name:''};modal(id?t('Renommer le projet','Rename the project'):t('Un nouveau projet','A new project'),t('Un titre suffit. Le contexte et les documents s’ajoutent ensuite, dans le projet.','A title is enough. Context and documents are added afterwards, in the project.'),field('name',t('Titre du projet','Project title'),p.name,t('Ex. Étude de marché','E.g. Market study'),'text','required maxlength="100"'),'projects',id?t('Enregistrer','Save'):t('Créer le projet','Create the project'),id)}
const formats=()=>[['pdf','PDF',t('Document prêt à imprimer','Print-ready document'),'#d93a3a','PDF'],['docx','Word',t('Modifiable, formules incluses','Editable, formulas included'),'#2b5fb4','W'],['pptx','PowerPoint',t('Diapositives de présentation','Presentation slides'),'#d0532b','P'],['tex','LaTeX',t('Source pour les formules','Source for formulas'),'#2f7d6d','TeX']];
function formatLogo(id,size=34){const f=formats().find(f=>f[0]===id);if(!f)return '';const s=f[4];return `<svg class="format-logo" width="${size}" height="${size}" viewBox="0 0 40 40" aria-hidden="true"><path d="M8 3h17l9 9v23a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2z" fill="${f[3]}"/><path d="M25 3v7a2 2 0 0 0 2 2h7z" fill="#fff" opacity=".45"/><text x="20" y="${s.length>1?29:30}" text-anchor="middle" font-family="Inter,Arial,sans-serif" font-weight="700" font-size="${s.length>2?9.5:s.length>1?10.5:15}" fill="#fff">${s}</text></svg>`}
function formatChoices(){return `<div class="field"><span class="label">${t('Format du livrable','Deliverable format')} <span class="field-help">${t('(facultatif)','(optional)')}</span></span><div class="format-row">${formats().map(([id,l,d])=>`<label class="format-pill" title="${esc(d)}"><input type="checkbox" name="formats" value="${id}">${formatLogo(id,24)}<span>${l}</span></label>`).join('')}</div></div>`}
function missionModal(team=''){if(!state.teams.length){toast(t('Créez d’abord une équipe.','Create a team first.'));teamModal();return}modal(t('Que voulez-vous accomplir ?','What do you want to achieve?'),t('Décrivez le résultat attendu. Votre équipe s’occupe de la suite.','Describe the expected result. Your team takes it from there.'),textarea('brief',t('Votre objectif','Your goal'),'',t('Ce que vous souhaitez obtenir, les documents à utiliser et les contraintes à respecter…','What you want to get, the documents to use and the constraints to respect…'),'required maxlength="20000"')+`<div class="form-grid">${state.projects.length?select('project_id',t('Projet','Project'),state.projects.map(p=>[p.id,p.name]),route==='project'?currentId:state.projects[0].id):field('new_project',t('Votre premier projet','Your first project'),'',t('Ex. Mon premier projet','E.g. My first project'),'text','required maxlength="100"')}${select('team_id',t('Équipe','Team'),state.teams.map(x=>[x.id,x.name]),team||state.teams[0].id)}</div>`+formatChoices()+`<details class="mt"><summary class="textbtn">${t('Options avancées','Advanced options')}</summary>${field('name',t('Nom de la mission (facultatif)','Mission name (optional)'),'',t('Par défaut, le début de l’objectif','Defaults to the start of the goal'),'text','maxlength="140"')}<label class="choice"><input type="checkbox" name="verify" checked><div><strong>${t('Vérifier automatiquement les sources','Check sources automatically')}</strong><small>${t('Chaque lien, DOI ou référence arXiv cité est contrôlé, sans IA. Une source introuvable est renvoyée à l’agent pour correction, deux fois au plus.','Every cited link, DOI or arXiv reference is checked, without AI. A source that cannot be found is sent back to the agent for correction, twice at most.')}</small></div></label>${!state.demo?`<label class="choice"><input type="radio" name="execution" value="live" checked><div><strong>${t('Mission réelle','Real mission')}</strong><small>${t('Les agents utilisent les comptes connectés sur la VM.','Agents use the accounts logged in on the VM.')}</small></div></label>`:''}<label class="choice"><input type="radio" name="execution" value="demo" ${state.demo?'checked':''}><div><strong>${t('Essayer en démonstration','Try in demo mode')}</strong><small>${t('Un parcours simulé, sans appel aux assistants.','A simulated run, with no call to the assistants.')}</small></div></label><label class="checkbox-line"><input type="checkbox" name="allow_write" checked>${t('Autoriser la création et la modification de fichiers','Allow creating and editing files')}</label><label class="checkbox-line"><input type="checkbox" name="review">${t('Me demander de valider entre les étapes','Ask me to approve between steps')}</label><div class="mt">${field('timeout_minutes',t('Durée maximale par agent (minutes)','Time limit per agent (minutes)'),45,'','number','min="1" max="120" required')}</div></details>`,'mission',t('Lancer la mission','Start the mission'))}
function renderLogin(){const configured=session?.configured;$('#app').innerHTML=`<div class="login-screen"><div class="login-art"><div><a class="brand"><img src="./favicon.svg" alt="">atelier</a><h1>${t('Vos idées.<br>Votre équipe.<br>Votre atelier.','Your ideas.<br>Your team.<br>Your atelier.')}</h1><p>${t('Un espace pour donner le cap, faire travailler vos agents et retrouver ce qu’ils créent pour vous.','A space to set the course, put your agents to work and find what they create for you.')}</p></div></div><div class="login-box"><form id="login-form"><div class="login-lang">${langSwitch()}</div><p class="eyebrow">${t('VOTRE ESPACE PERSONNEL','YOUR PERSONAL SPACE')}</p><h2>${t('Bienvenue dans votre atelier.','Welcome to your atelier.')}</h2><p class="sub">${configured?t('Connectez-vous pour retrouver vos projets et vos agents.','Log in to find your projects and agents.'):t('Définissez d’abord un mot de passe sur la machine : python3 server.py --init (voir le README).','First set a password on the machine: python3 server.py --init (see the README).')}</p><div id="login-error" class="form-error hidden"></div>${configured?field('password',t('Votre mot de passe','Your password'),'','','password','required autocomplete="current-password"')+'<button class="btn primary" type="submit">'+t('Ouvrir mon atelier ','Open my atelier ')+icon('arrow')+'</button>':''}<p class="footer-note">${t('Hébergé dans votre environnement · Accès personnel','Hosted in your environment · Personal access')}</p></form></div></div>`}
async function refresh(){if(refreshing||!session?.authenticated)return;refreshing=true;try{const next=await api('/state');if(!session?.authenticated)return;state=next;if(route==='mission'&&currentId){const id=currentId;const m=await api('/missions/'+id);if(route==='mission'&&currentId===id){const changed=!detail||JSON.stringify(m)!==JSON.stringify(detail);detail=m;if(changed&&!$('#modal-form')&&!$('#note-form input:focus')&&!document.querySelector('.event details[open]')&&!window.getSelection()?.toString())renderPage()}}else if(route==='overview'&&!$('#modal-form'))renderPage()}catch(e){if(!session?.authenticated)return;console.warn('Refresh unavailable')}finally{refreshing=false}}
async function boot(){try{session=await api('/session');if(session.language)setLang(session.language);if(!session.authenticated){renderLogin();return}state=await api('/state');if(!state.language&&!state.demo){await api('/settings/language','PUT',{language:lang});state=await api('/state')}await navigate()}catch(e){$('#app').innerHTML=`<div class="loading">${esc(e.message)} ${t('Rechargez la page pour réessayer.','Reload the page to try again.')}</div>`}}
async function changeLang(next){setLang(next);if(session?.authenticated){await api('/settings/language','PUT',{language:lang});state=await api('/state');if(detail)detail=await api('/missions/'+detail.id);shell()}else renderLogin()}
window.addEventListener('hashchange',()=>{if(session?.authenticated)navigate()});
document.addEventListener('click',async ev=>{const target=ev.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;try{switch(action){case'set-lang':await changeLang(id);break;case'menu':$('.sidebar').classList.toggle('open');break;case'close-modal':closeModal();break;case'new-agent':agentModal();break;case'edit-agent':agentModal(id);break;case'new-team':teamModal();break;case'edit-team':teamModal(id);break;case'new-project':projectModal();break;case'edit-project':projectModal(id);break;case'new-mission':missionModal();break;case'use-team':missionModal(id);break;case'team-up':{const i=teamOrder.indexOf(id);if(i>0)[teamOrder[i-1],teamOrder[i]]=[teamOrder[i],teamOrder[i-1]];$('#team-choices').innerHTML=teamChoices();break}case'team-remove':teamOrder=teamOrder.filter(a=>a!==id);$('#team-choices').innerHTML=teamChoices();break;case'detail-tab':detailTab=id;renderPage();break;case'delete-agent':case'delete-team':case'delete-project':case'delete-mission':{const kind={'delete-agent':'agents','delete-team':'teams','delete-project':'projects','delete-mission':'missions'}[action];const obj=kind==='missions'&&detail?.id===id?detail:find(kind,id);modal(t('Supprimer « ','Delete “')+esc(obj.name)+t(' » ?','”?'),t('Cette suppression est définitive.','This cannot be undone.'),'<p class="sub">'+deleteNotice(kind,obj)+'</p>','delete-'+kind,t('Supprimer définitivement','Delete permanently'),id);break}case'delete-file':{await api('/projects/'+currentId+'/files','DELETE',{path:target.dataset.path});projectDetail();toast(t('Document supprimé.','Document deleted.'));break}case'test-antigravity':{target.disabled=true;target.textContent=t('Mission de test en cours…','Test mission running…');try{const r=await api('/connections/antigravity/test','POST',{});toast(t('Mission de test réussie (','Test mission succeeded (')+r.model+').')}finally{state.connections=await api('/connections','POST',{});$('#connections').innerHTML=connectionsHTML(state.connections)}break}case'check-connections':target.disabled=true;target.textContent=t('Vérification…','Checking…');state.connections=await api('/connections','POST',{});$('#connections').innerHTML=connectionsHTML(state.connections);target.disabled=false;target.textContent=t('Vérifier les connexions','Check connections');break;case'dismiss-download':detail=await api('/missions/'+currentId+'/action','POST',{action:'dismiss',step:Number(target.dataset.step),text:target.dataset.text});state=await api('/state');renderPage();break;case'revise-mission':modal(t('Demander une retouche','Ask for a revision'),t('Seul l’agent final reprend le livrable actuel et applique votre demande.','Only the final agent picks up the current deliverable and applies your request.'),textarea('text',t('Ce qu’il faut changer','What to change'),'',t('Ex. Ajoute une diapositive sur les prix, rends la palette plus sobre, raccourcis la conclusion…','E.g. Add a slide on prices, make the palette more sober, shorten the conclusion…'),'required maxlength="6000"'),'revise',t('Lancer la retouche','Start the revision'),currentId);break;case'delete-reference':state.references=await api('/references','DELETE',{format:target.dataset.format,name:target.dataset.name});renderPage();toast(t('Exemple retiré.','Example removed.'));break;case'pause-mission':await missionAction('pause');break;case'resume-mission':await missionAction(detail.status==='waiting'?'approve':'resume');break;case'stop-mission':modal(t('Arrêter cette mission ?','Stop this mission?'),t('Les contributions déjà produites seront conservées.','Contributions already produced will be kept.'),`<p class="sub">${t('Les agents en cours seront arrêtés. Vous pourrez créer une nouvelle mission si vous souhaitez poursuivre.','Running agents will be stopped. You can create a new mission if you want to go on.')}</p>`,'stop',t('Arrêter la mission','Stop the mission'),currentId);break;case'logout':await api('/logout','POST',{});session.authenticated=false;renderLogin();break;case'password':modal(t('Changer votre mot de passe','Change your password'),t('Vous devrez vous reconnecter après l’enregistrement.','You will need to log in again after saving.'),field('current',t('Mot de passe actuel','Current password'),'','','password','required autocomplete="current-password"')+field('password',t('Nouveau mot de passe','New password'),'',t('12 caractères minimum','12 characters minimum'),'password','required minlength="12" autocomplete="new-password"'),'password',t('Enregistrer','Save'));break}}catch(e){toast(e.message);target.disabled=false}});
async function missionAction(action){detail=await api('/missions/'+currentId+'/action','POST',{action});detail=await api('/missions/'+currentId);renderPage();toast(action==='pause'?t('Pause demandée.','Pause requested.'):t('Mission mise à jour.','Mission updated.'))}
const readFile=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});
const tooBig=file=>Error(file.name+t(' dépasse la limite de 20 Mo.',' exceeds the 20 MB limit.'));
document.addEventListener('change',async e=>{if(e.target.id==='f-preset'){$('#role-fields').innerHTML=roleFields(e.target.value);return}if(e.target.id==='team-add-agent'&&e.target.value){if(teamOrder.length>=6){toast(t('Une équipe peut contenir 6 agents maximum.','A team can have 6 agents at most.'));return}const isLast=x=>find('agents',x)?.preset==='relecteur';const at=isLast(e.target.value)?-1:teamOrder.findIndex(isLast);if(at<0)teamOrder.push(e.target.value);else teamOrder.splice(at,0,e.target.value);$('#team-choices').innerHTML=teamChoices()}if(e.target.classList.contains('reference-upload')&&e.target.files[0]){const file=e.target.files[0];try{if(file.size>20*1024*1024)throw tooBig(file);toast(t('Ajout de l’exemple et préparation des aperçus…','Adding the example and preparing previews…'));state.references=await api('/references','POST',{format:e.target.dataset.format,name:file.name,content:await readFile(file)});renderPage();toast(t('Exemple ajouté.','Example added.'))}catch(err){toast(err.message)}return}if(e.target.id==='upload'){const input=e.target;input.disabled=true;try{for(const file of input.files){if(file.size>20*1024*1024)throw tooBig(file);await api('/projects/'+currentId+'/files','POST',{name:file.name,content:await readFile(file)})}toast(t('Documents ajoutés au projet.','Documents added to the project.'));projectDetail()}catch(err){toast(err.message)}finally{input.disabled=false}}});
document.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target;const values=Object.fromEntries(new FormData(form));const submit=form.querySelector('button[type=submit]');if(submit)submit.disabled=true;try{if(form.id==='login-form'){await api('/login','POST',values);await boot();return}if(form.id==='note-form'){await api('/missions/'+currentId+'/action','POST',{action:'note',text:values.text});form.reset();await refresh();toast(t('Précision ajoutée pour la prochaine étape.','Note added for the next step.'));return}if(form.id==='context-form'){const r=await api('/settings/context','PUT',{global_context:values.global_context});state.global_context=r.global_context;toast(t('Contexte global enregistré. Il s’appliquera aux prochaines missions.','Global context saved. It will apply to future missions.'));return}if(form.id==='project-context-form'){const p=find('projects',currentId);await api('/projects/'+currentId,'PUT',{name:p.name,description:values.project_context});state=await api('/state');toast(t('Contexte enregistré. Il s’appliquera aux prochaines missions.','Context saved. It will apply to future missions.'));return}if(form.id!=='modal-form')return;const kind=form.dataset.form,id=form.dataset.id;if(kind==='mission'){if(values.new_project){const p=await api('/projects','POST',{name:values.new_project,description:''});values.project_id=p.id}values.allow_write=!!values.allow_write;values.review=!!values.review;values.formats=new FormData(form).getAll('formats');values.verify=!!values.verify;values.timeout_minutes=Number(values.timeout_minutes);const m=await api('/missions','POST',values);closeModal();state=await api('/state');location.hash='mission/'+m.id;toast(t('Mission créée. Votre équipe va démarrer.','Mission created. Your team is about to start.'));return}if(kind==='revise'){await api('/missions/'+id+'/action','POST',{action:'revise',text:values.text});closeModal();detailTab='activity';await refresh();toast(t('Retouche lancée.','Revision started.'));return}if(kind==='stop'){await api('/missions/'+id+'/action','POST',{action:'cancel'});closeModal();await refresh();return}if(kind.startsWith('delete-')){const gone=kind.slice(7);const project=gone==='missions'?(detail?.project_id||find('missions',id)?.project_id):'';await api('/'+gone+'/'+id,'DELETE',{});if(gone==='missions'||gone==='projects'){closeModal();state=await api('/state');const next=gone==='missions'&&project?'project/'+project:'projects';if(location.hash.slice(1)===next)navigate();else location.hash=next;toast(t('Suppression effectuée.','Deleted.'));return}}else if(kind==='password'){await api('/password','POST',values);closeModal();session.authenticated=false;renderLogin();toast(t('Mot de passe modifié. Reconnectez-vous.','Password changed. Log in again.'));return}else{if(kind==='teams')values.agent_ids=teamOrder;if(kind==='agents'&&!values.name.trim())values.name=state.roles?.[values.preset]?.label||'';const result=await api('/'+kind+(id?'/'+id:''),id?'PUT':'POST',values);if(kind==='projects'&&!id){state=await api('/state');closeModal();location.hash='project/'+result.id;toast(t('Projet créé. Vous pouvez ajouter vos documents.','Project created. You can add your documents.'));return}}closeModal();state=await api('/state');renderPage();toast(t('Modifications enregistrées.','Changes saved.'))}catch(err){const box=form.id==='login-form'?$('#login-error'):$('#form-error');if(box){box.textContent=err.message;box.classList.remove('hidden');box.scrollIntoView({block:'nearest'})}else toast(err.message)}finally{if(submit)submit.disabled=false}});
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const els=[...$('.modal').querySelectorAll('button:not([disabled]),input,textarea,select,summary,a[href]')].filter(x=>x.offsetParent!==null);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
setInterval(refresh,3000);boot();
